import{z as m,x as B,o as t,c as d,q as n,j as o,D as e,d as r,s,S as E,b as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"树状数组","description":"","frontmatter":{"title":"树状数组","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fenwick-tree.md","filePath":"cs/fenwick-tree.md","lastUpdated":1791413859000}'),p={name:"cs/fenwick-tree.md"};function A(c,a,C,h,D,b){const l=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="树状数组" tabindex="-1">树状数组 <a class="header-anchor" href="#树状数组" aria-label="Permalink to &quot;树状数组&quot;">​</a></h1><div class="epigraph"><p>每个下标负责一段以自己为右端、长度为最低位 1 的前缀碎片；改一点只走祖先，问前缀只走低位清零。</p><footer>—— 据 Fenwick, A New Data Structure for Cumulative Frequency Tables, Software: Practice and Experience, 1994；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/sparse-table">上一课</a>把静态幂等查询钉成 \\(O(1)\\)，数组一改就整表作废。<a href="/cs/prefix-sum-difference">前缀和</a>同样经不起单点修改。本课不重讲倍增窗口。缺口是：<strong>可更新的前缀和</strong>——树状数组（Fenwick / binary indexed tree），单点加与前缀和都是 \\(O(\\log n)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>需要维护 \\(A[1..n]\\)，操作是 \\(A[i]\\mathrel{+}=d\\) 以及查询 \\(S[r]=\\sum_{i=1}^{r}A[i]\\)。线段树也能做，但节点数约 \\(4n\\)、常数更大。Fenwick 用 \\(n\\) 个格子：下标 \\(i\\) 存 \\(\\sum A\\) 在区间 \\((i-\\mathrm{lowbit}(i),i]\\) 上的和，其中 \\(\\mathrm{lowbit}(i)=i\\,\\&amp;\\,{-i}\\)。缺口不是新的群，仍是加法；是<strong>用二进制进位结构代替递归线段</strong>。</p><p>区间和仍是 \\(S[r]-S[l-1]\\)。区间加可再套一层差分，本课先钉点修前缀查。</p><p><span class="marginnote">数字实例：\\(\\mathrm{lowbit}\\) 就是取二进制里最低的那个 1：\\(6 = 110_2\\)，lowbit 为 \\(2\\)；\\(12 = 1100_2\\)，lowbit 为 \\(4\\)。于是 \\(C[12]\\) 负责从第 9 到第 12 这 4 个数的和——负责多长，正好等于下标二进制里末尾那个「1」的分量大小。</span></p><p><span class="marginnote">lowbit 来自补码：\\(-i=\\sim i+1\\)，与 \\(i\\) 只在最低的 1 及其右侧为零处相交。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>更新 \\(i\\)：当 \\(i\\le n\\) 时把 \\(C[i]\\) 加上 \\(d\\)，再 \\(i\\mathrel{+}=\\mathrm{lowbit}(i)\\)。查询前缀 \\(r\\)：累加 \\(C[r]\\)，再 \\(r\\mathrel{-}=\\mathrm{lowbit}(r)\\)，直到 \\(0\\)。两次都 \\(O(\\log n)\\) 步。下标从 \\(1\\) 起；不要用 \\(0\\)，lowbit 会停住。</p>',10)),(t(),o(E,null,{default:e(()=>[s(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E4%B8%8B%E6%A0%87%20i%22%5D%20--%3E%20LB%5B%22lowbit%20%3D%20i%20AND%20-i%22%5D%0A%20%20LB%20--%3E%20UP%5B%22%E6%9B%B4%E6%96%B0%3A%20i%20%2B%3D%20lowbit%22%5D%0A%20%20LB%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%3A%20i%20-%3D%20lowbit%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("p",null,"初始化可逐点更新 \\(\\Theta(n\\log n)\\)，或按 \\(A\\) 扫一遍把贡献加到 \\(C[i]\\) 再向上，\\(O(n)\\)。",-1)),a[4]||(a[4]=i("h2",{id:"机制",tabindex:"-1"},[r("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=i("p",null,"每个 \\(A[j]\\) 出现在哪些 \\(C[i]\\)：所有 \\(i\\ge j\\) 且 \\((i-\\mathrm{lowbit}(i),i]\\) 盖住 \\(j\\) 的那些。沿 \\(i\\mathrel{+}=\\mathrm{lowbit}\\) 恰好走完覆盖 \\(j\\) 的祖先。查询沿清低位走的是一段段不相交、并起来等于 \\([1,r]\\) 的块。",-1)),(t(),o(E,null,{default:e(()=>[s(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20S%2013%22%5D%20--%3E%20C13%5B%2213%3D1101%3A%20%E5%8F%96%20C13%2C%20%E8%A6%86%E7%9B%96%20(12%2C13%5D%22%5D%0A%20%20C13%20--%3E%20C12%5B%2213%20%E6%B8%85%E6%8E%89%E6%9C%80%E4%BD%8E%E4%BD%8D%E5%BE%97%2012%3A%20%E5%8F%96%20C12%2C%20%E8%A6%86%E7%9B%96%20(8%2C12%5D%22%5D%0A%20%20C12%20--%3E%20C8%5B%2212%20%E6%B8%85%E6%8E%89%E6%9C%80%E4%BD%8E%E4%BD%8D%E5%BE%97%208%3A%20%E5%8F%96%20C8%2C%20%E8%A6%86%E7%9B%96%20(0%2C8%5D%22%5D%0A%20%20C8%20--%3E%20Z%5B%22%E5%88%B0%200%20%E5%81%9C%3A%20%E4%B8%89%E5%9D%97%E4%B8%8D%E7%9B%B8%E4%BA%A4%2C%20%E6%8B%BC%E5%87%BA%201..13%22%5D%0A%20%20U%5B%22%E5%8D%95%E7%82%B9%E5%8A%A0%E5%9C%A8%205%22%5D%20--%3E%20C5%5B%22C5%20%E5%8A%A0%20d%22%5D%0A%20%20C5%20--%3E%20C6%5B%22%E8%B7%B3%E5%88%B0%206%20%3D%205%20%2B%20lowbit%201%22%5D%0A%20%20C6%20--%3E%20C8B%5B%22%E8%B7%B3%E5%88%B0%208%20%3D%206%20%2B%20lowbit%202%22%5D%0A%20%20C8B%20--%3E%20C16%5B%22%E8%B7%B3%E5%88%B0%2016%20%3D%208%20%2B%20lowbit%208%2C%20%E5%81%9C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比：查询像用二进制面额的硬币凑零钱——凑 \\(13 = 8 + 4 + 1\\)，一次取走面额合适的整块，最多 \\(\\log n\\) 枚。更新则相反：往 1 块钱投进点数后，要给所有「装有这枚硬币的钱箱」（高位祖先）都补记账。一个向下拆块，一个向上补账，方向正好相反。</span></p><p>空间 \\(\\Theta(n)\\)，比线段树瘦。缓存：跳 \\(\\mathrm{lowbit}\\) 比连续扫跳得散，但步数只有 \\(\\log n\\)。二维 Fenwick 同构嵌套，本课不展开。</p><p>与<a href="/cs/array-random-access">数组随机访问</a>：\\(C\\) 仍是数组，只是语义按二进制区间切。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>运算须可结合、通常要可逆（区间用两个前缀）。最值也可以做，但「单点改成任意值」比「只加」麻烦，实践多换线段树。本课不写树上差分、不写权值树状数组套主席树。</p><p>后课默认：点修前缀和用 Fenwick 即可。要任意结合律、区间改、或存整段懒更新，下一课线段树。</p><p><span class="marginnote">常见误区：初学者容易把更新和查询的跳法记反，或用下标 \\(0\\) 起头。\\(\\mathrm{lowbit}(0) = 0\\)，两个方向都会原地打转死循环——这正是树状数组约定下标从 1 开始的原因。方向记反则更隐蔽：查询会漏块或重复，结果看似合理却不等。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Fenwick：lowbit 切前缀碎片，点修与前缀查询 \\(O(\\log n)\\)。</li><li>空间 \\(n\\)；下标从 1。</li><li>更一般的区间运算交给线段树。</li><li>出处：Fenwick, <em>Software: Practice and Experience</em>, 1994；Cormen et al.。</li></ul>',9))])}const u=m(p,[["render",A]]);export{f as __pageData,u as default};
